import fs, { existsSync } from 'node:fs';
import { stat } from 'node:fs/promises';
import path from 'node:path';
import AdmZip from 'adm-zip';
import { CONVERT_BYTES_TO_MB, MAX_ASSET_SIZE } from '../../constants.js';
import { getDependencyInfo, takeAutoInstallManifest, } from './dependency-info.js';
import { detectNativeModules, errorMessage } from './detect-native-modules.js';
import { isFolderLargerThan } from './is-folder-larger-than.js';
import { resolveResourceDependencies } from './resolve-dependencies.js';
import { shouldAutoResolveDependencies } from './should-auto-resolve-deps.js';
import { shouldTranspileFunction } from './should-transpile.js';
import { transpileFunction } from './transpile/function.js';
export async function prepareAsset({ blueprintFileDir, resource, installer, }) {
    if (!resource.src)
        throw new Error('Resource src is required');
    const resolvedFunctionPath = path.resolve(blueprintFileDir, resource.src);
    let functionPath = resolvedFunctionPath;
    let cleanup = async () => { };
    let wasBundled = false;
    let dependenciesInstalled = false;
    let autoInstall;
    const shouldTranspile = await shouldTranspileFunction(resource, functionPath);
    if (shouldTranspile.transpile) {
        try {
            const result = await transpileFunction({
                resource,
                functionPath,
                entryPoint: shouldTranspile.entryPoint,
                installer,
            });
            functionPath = result.outputDir;
            cleanup = result.cleanup;
            wasBundled = result.bundled;
        }
        catch (err) {
            return { success: false, cleanup, error: err instanceof Error ? err.message : `${err}` };
        }
    }
    const shouldResolveDependencies = await shouldAutoResolveDependencies(resource);
    if (shouldResolveDependencies && !wasBundled) {
        await resolveResourceDependencies({
            resource,
            functionPath: resolvedFunctionPath,
            blueprintFileDir,
            transpiled: shouldTranspile.transpile,
            installer,
        });
        autoInstall = await takeAutoInstallManifest(functionPath);
        dependenciesInstalled = true;
    }
    if (existsSync(path.join(functionPath, 'node_modules'))) {
        const modulesPath = path.join(functionPath, 'node_modules');
        const flagged = detectNativeModules(modulesPath);
        if (flagged.length > 0) {
            throw new Error(errorMessage(flagged));
        }
    }
    try {
        // First check the size before trying to create the zip file
        const result = isFolderLargerThan(functionPath, MAX_ASSET_SIZE);
        if (result) {
            throw new Error('Resource is larger than max asset size of 200 MB.');
        }
        const zip = await pathToZip(functionPath);
        // Add up the uncompressed sizes of all entries to get a more accurate size of the asset being uploaded
        const zipEntrySize = zip
            .getEntries()
            .map((entry) => entry.header.size)
            .reduce((a, b) => a + b, 0);
        if (zipEntrySize > MAX_ASSET_SIZE) {
            throw new Error(`Asset size of ${(zipEntrySize / CONVERT_BYTES_TO_MB).toFixed(2)} MB exceeds the maximum allowed size of 200 MB.`);
        }
        return {
            success: true,
            outputBuffer: await zip.toBufferPromise(),
            fileExtension: 'zip',
            assetParameter: 'src',
            cleanup,
            metadata: {
                transpiled: shouldTranspile.transpile,
                bundled: wasBundled,
                dependenciesInstalled,
                ...(await getDependencyInfo({
                    sourceDir: resolvedFunctionPath,
                    autoInstall,
                    bundled: wasBundled,
                })),
                assetBytes: zipEntrySize,
            },
        };
    }
    catch (err) {
        return { success: false, cleanup, error: err instanceof Error ? err.message : `${err}` };
    }
}
export async function pathToZip(path) {
    const stats = await stat(path);
    const zip = new AdmZip(undefined, {
        fs: {
            ...fs,
            // @ts-expect-error monkey patching to return matching mtime for builds
            statSync(path, options) {
                const s = fs.statSync(path, options);
                if (s)
                    s.mtime = new Date(0);
                return s;
            },
        },
    });
    if (stats.isDirectory())
        zip.addLocalFolder(path);
    else
        zip.addLocalFile(path, '', 'index.js');
    return zip;
}
